      hv_Size_COPY_INP_TMP.Dispose();
      hv_OS.Dispose();
      hv_Fonts.Dispose();
      hv_Style.Dispose();
      hv_Exception.Dispose();
      hv_AvailableFonts.Dispose();
      hv_Fdx.Dispose();
      hv_Indices.Dispose();

      return;
    }
    catch (HalconException HDevExpDefaultException)
    {

      hv_Font_COPY_INP_TMP.Dispose();
      hv_Size_COPY_INP_TMP.Dispose();
      hv_OS.Dispose();
      hv_Fonts.Dispose();
      hv_Style.Dispose();
      hv_Exception.Dispose();
      hv_AvailableFonts.Dispose();
      hv_Fdx.Dispose();
      hv_Indices.Dispose();

      throw HDevExpDefaultException;
    }
  }

  // Local procedures 
  public void display_results (HObject ho_ImageAffineTrans, HObject ho_LeftOvers, 
      HObject ho_FinalClasses, HObject ho_WrongPills, HTuple hv_CountFinalClass, HTuple hv_PillTypeCount, 
      HTuple hv_WindowHandle)
  {




    // Local iconic variables 

    HObject ho_RedLeftOvers, ho_ObjectSelected;

    // Local control variables 

    HTuple hv_ThereWereErrors = new HTuple(), hv_PillType = new HTuple();
    HTuple hv_Numbers = new HTuple(), hv_Message = new HTuple();
    HTuple hv_Errors = new HTuple(), hv_Colors = new HTuple();
    HTuple hv_NumWrong = new HTuple();
    // Initialize local and output iconic variables 
    HOperatorSet.GenEmptyObj(out ho_RedLeftOvers);
    HOperatorSet.GenEmptyObj(out ho_ObjectSelected);
    try
    {
      hv_ThereWereErrors.Dispose();
      hv_ThereWereErrors = 0;
      if (HDevWindowStack.IsOpen())
      {
        HOperatorSet.DispObj(ho_ImageAffineTrans, HDevWindowStack.GetActive());
      }
      if (HDevWindowStack.IsOpen())
      {
        HOperatorSet.SetDraw(HDevWindowStack.GetActive(), "margin");
      }
      if (HDevWindowStack.IsOpen())
      {
        HOperatorSet.SetLineWidth(HDevWindowStack.GetActive(), 4);
      }
      if (HDevWindowStack.IsOpen())
      {
        HOperatorSet.SetColor(HDevWindowStack.GetActive(), "red");
      }
      ho_RedLeftOvers.Dispose();
      HOperatorSet.DilationCircle(ho_LeftOvers, out ho_RedLeftOvers, 2.5);
      if (HDevWindowStack.IsOpen())
      {
        HOperatorSet.DispObj(ho_RedLeftOvers, HDevWindowStack.GetActive());
      }
      //
      if (HDevWindowStack.IsOpen())
      {
        HOperatorSet.SetLineWidth(HDevWindowStack.GetActive(), 3);
      }
      ho_ObjectSelected.Dispose();
      HOperatorSet.SelectObj(ho_FinalClasses, out ho_ObjectSelected, 1);
      if (HDevWindowStack.IsOpen())
      {
        HOperatorSet.SetColor(HDevWindowStack.GetActive(), "goldenrod");
      }
      if (HDevWindowStack.IsOpen())
      {
        HOperatorSet.DispObj(ho_ObjectSelected, HDevWindowStack.GetActive());
      }
      ho_ObjectSelected.Dispose();
      HOperatorSet.SelectObj(ho_FinalClasses, out ho_ObjectSelected, 3);
      if (HDevWindowStack.IsOpen())
      {
        HOperatorSet.SetColor(HDevWindowStack.GetActive(), "medium forest green");
      }
      if (HDevWindowStack.IsOpen())
      {
        HOperatorSet.DispObj(ho_ObjectSelected, HDevWindowStack.GetActive());
      }
      ho_ObjectSelected.Dispose();
      HOperatorSet.SelectObj(ho_FinalClasses, out ho_ObjectSelected, 2);
      if (HDevWindowStack.IsOpen())
      {
        HOperatorSet.SetColor(HDevWindowStack.GetActive(), "firebrick");
      }
      if (HDevWindowStack.IsOpen())
      {
        HOperatorSet.DispObj(ho_ObjectSelected, HDevWindowStack.GetActive());
      }
      //
      hv_PillType.Dispose();
      using (HDevDisposeHelper dh = new HDevDisposeHelper())
      {
      hv_PillType = ((
          (new HTuple("\"yellow\"")).TupleConcat("\"red\"")).TupleConcat("\"green\"")).TupleString(
          "-8");
      }
      hv_Numbers.Dispose();
      using (HDevDisposeHelper dh = new HDevDisposeHelper())
      {
      hv_Numbers = (("# Pill type "+hv_PillType)+": ")+hv_CountFinalClass;
      }
      hv_Message.Dispose();
      using (HDevDisposeHelper dh = new HDevDisposeHelper())
      {
      hv_Message = ("# Pill type "+hv_PillType)+": ";
      }
      hv_Errors.Dispose();
      using (HDevDisposeHelper dh = new HDevDisposeHelper())
      {
      hv_Errors = ((hv_CountFinalClass.TupleNotEqualElem(
          hv_PillTypeCount))).TupleString("1");
      }
      hv_Colors.Dispose();
      using (HDevDisposeHelper dh = new HDevDisposeHelper())
      {
      hv_Colors = hv_Errors.TupleRegexpReplace(
          "0","black");
      }
      using (HDevDisposeHelper dh = new HDevDisposeHelper())
      {
      {
      HTuple 
        ExpTmpLocalVar_Colors = hv_Colors.TupleRegexpReplace(
          "1","red");
      hv_Colors.Dispose();
      hv_Colors = ExpTmpLocalVar_Colors;
      }
      }
      //
      disp_message(hv_WindowHandle, hv_Numbers, "window", 10, 10, hv_Colors, "true");
      //
      hv_NumWrong.Dispose();
      HOperatorSet.CountObj(ho_WrongPills, out hv_NumWrong);
      if ((int)(new HTuple(hv_NumWrong.TupleGreater(0))) != 0)
      {
        using (HDevDisposeHelper dh = new HDevDisposeHelper())
        {
        disp_message(hv_WindowHandle, "# Wrong pill type   : "+hv_NumWrong, "window", 
            10+60, 10, "red", "true");
        }
      }
      if ((int)(new HTuple(((hv_Errors.TupleFind("1"))).TupleNotEqual(-1))) != 0)
      {
        disp_message(hv_WindowHandle, "Not OK", "window", 10, 600, "red", "true");
      }
      else
      {
        disp_message(hv_WindowHandle, "OK", "window", 10, 600, "forest green", "true");
      }
      ho_RedLeftOvers.Dispose();
      ho_ObjectSelected.Dispose();

      hv_ThereWereErrors.Dispose();
      hv_PillType.Dispose();
      hv_Numbers.Dispose();
      hv_Message.Dispose();
      hv_Errors.Dispose();
      hv_Colors.Dispose();
      hv_NumWrong.Dispose();

      return;
    }
    catch (HalconException HDevExpDefaultException)
    {
      ho_RedLeftOvers.Dispose();
      ho_ObjectSelected.Dispose();

      hv_ThereWereErrors.Dispose();
      hv_PillType.Dispose();
      hv_Numbers.Dispose();
      hv_Message.Dispose();
      hv_Errors.Dispose();
      hv_Colors.Dispose();
      hv_NumWrong.Dispose();

      throw HDevExpDefaultException;
    }
  }

  public void extract_pill_types (HObject ho_Image, out HObject ho_Chambers, out HObject ho_ChambersUnion, 
      out HObject ho_Classes, out HTuple hv_PhiRef, out HTuple hv_RowRef, out HTuple hv_ColumnRef, 
      out HTuple hv_PillTypeCount)
  {



    // Stack for temporary objects 
    HObject[] OTemp = new HObject[20];

    // Local iconic variables 

    HObject ho_Region, ho_ConnectedRegions, ho_SelectedRegions;
    HObject ho_Blister, ho_Rectangle=null, ho_Pattern, ho_PillType1;
    HObject ho_PillType2, ho_PillType3, ho_ImageReduced, ho_ImageR;
    HObject ho_ImageG, ho_ImageB, ho_ImageInvert, ho_RegionHysteresis2;
    HObject ho_RegionHysteresis3;

    // Local control variables 

    HTuple hv_I = new HTuple(), hv_Row = new HTuple();
    HTuple hv_J = new HTuple(), hv_Column = new HTuple(), hv_Area = new HTuple();
    // Initialize local and output iconic variables 
    HOperatorSet.GenEmptyObj(out ho_Chambers);
    HOperatorSet.GenEmptyObj(out ho_ChambersUnion);
    HOperatorSet.GenEmptyObj(out ho_Classes);
    HOperatorSet.GenEmptyObj(out ho_Region);
    HOperatorSet.GenEmptyObj(out ho_ConnectedRegions);
    HOperatorSet.GenEmptyObj(out ho_SelectedRegions);
    HOperatorSet.GenEmptyObj(out ho_Blister);
    HOperatorSet.GenEmptyObj(out ho_Rectangle);
    HOperatorSet.GenEmptyObj(out ho_Pattern);
    HOperatorSet.GenEmptyObj(out ho_PillType1);
    HOperatorSet.GenEmptyObj(out ho_PillType2);
    HOperatorSet.GenEmptyObj(out ho_PillType3);
    HOperatorSet.GenEmptyObj(out ho_ImageReduced);
    HOperatorSet.GenEmptyObj(out ho_ImageR);
    HOperatorSet.GenEmptyObj(out ho_ImageG);
    HOperatorSet.GenEmptyObj(out ho_ImageB);
    HOperatorSet.GenEmptyObj(out ho_ImageInvert);
    HOperatorSet.GenEmptyObj(out ho_RegionHysteresis2);
    HOperatorSet.GenEmptyObj(out ho_RegionHysteresis3);
    hv_PhiRef = new HTuple();
    hv_RowRef = new HTuple();
    hv_ColumnRef = new HTuple();
    hv_PillTypeCount = new HTuple();
    try
    {
      ho_Region.Dispose();
      HOperatorSet.Threshold(ho_Image, out ho_Region, 90, 255);
      ho_ConnectedRegions.Dispose();
      HOperatorSet.Connection(ho_Region, out ho_ConnectedRegions);
      ho_SelectedRegions.Dispose();
      HOperatorSet.SelectShape(ho_ConnectedRegions, out ho_SelectedRegions, "area", 
          "and", 5000, 999999);
      ho_Blister.Dispose();
      HOperatorSet.ShapeTrans(ho_SelectedRegions, out ho_Blister, "convex");
      ho_Chambers.Dispose();
      HOperatorSet.GenEmptyRegion(out ho_Chambers);
      for (hv_I=0; (int)hv_I<=4; hv_I = (int)hv_I + 1)
      {
        hv_Row.Dispose();
        using (HDevDisposeHelper dh = new HDevDisposeHelper())
        {
        hv_Row = 107+(hv_I*70);
        }
        for (hv_J=0; (int)hv_J<=2; hv_J = (int)hv_J + 1)
        {
          hv_Column.Dispose();
          using (HDevDisposeHelper dh = new HDevDisposeHelper())
          {
          hv_Column = 177+(hv_J*150);
          }
          ho_Rectangle.Dispose();
          HOperatorSet.GenRectangle2(out ho_Rectangle, hv_Row, hv_Column, 0, 64, 
              30);
          {
          HObject ExpTmpOutVar_0;
          HOperatorSet.ConcatObj(ho_Chambers, ho_Rectangle, out ExpTmpOutVar_0);
          ho_Chambers.Dispose();
          ho_Chambers = ExpTmpOutVar_0;
          }
        }
      }
      ho_Pattern.Dispose();
      HOperatorSet.Difference(ho_Blister, ho_Chambers, out ho_Pattern);
      ho_ChambersUnion.Dispose();
      HOperatorSet.Union1(ho_Chambers, out ho_ChambersUnion);
      hv_PhiRef.Dispose();
      HOperatorSet.OrientationRegion(ho_Blister, out hv_PhiRef);
      using (HDevDisposeHelper dh = new HDevDisposeHelper())
      {
      {
      HTuple 
        ExpTmpLocalVar_PhiRef = ((new HTuple(180)).TupleRad()
          )+hv_PhiRef;
      hv_PhiRef.Dispose();
      hv_PhiRef = ExpTmpLocalVar_PhiRef;
      }
      }
      hv_Area.Dispose();hv_RowRef.Dispose();hv_ColumnRef.Dispose();
      HOperatorSet.AreaCenter(ho_Blister, out hv_Area, out hv_RowRef, out hv_ColumnRef);
      //
      //
      // +++ Extract pattern for classification +++
      ho_PillType1.Dispose();
      HOperatorSet.SelectShape(ho_Chambers, out ho_PillType1, "row", "and", 1, 145);
      {
      HObject ExpTmpOutVar_0;
      HOperatorSet.Union1(ho_PillType1, out ExpTmpOutVar_0);
      ho_PillType1.Dispose();
      ho_PillType1 = ExpTmpOutVar_0;
      }
      ho_PillType2.Dispose();
      HOperatorSet.SelectShape(ho_Chambers, out ho_PillType2, "row", "and", 145, 
          270);
      {
      HObject ExpTmpOutVar_0;
      HOperatorSet.Union1(ho_PillType2, out ExpTmpOutVar_0);
      ho_PillType2.Dispose();
      ho_PillType2 = ExpTmpOutVar_0;
      }
      ho_PillType3.Dispose();
      HOperatorSet.SelectShape(ho_Chambers, out ho_PillType3, "row", "and", 270, 
          390);
      {
      HObject ExpTmpOutVar_0;
      HOperatorSet.Union1(ho_PillType3, out ExpTmpOutVar_0);
      ho_PillType3.Dispose();
      ho_PillType3 = ExpTmpOutVar_0;
      }
      //
      //
      //Extract color space of yellow pills
      ho_ImageReduced.Dispose();
      HOperatorSet.ReduceDomain(ho_Image, ho_PillType1, out ho_ImageReduced);
      ho_ImageR.Dispose();ho_ImageG.Dispose();ho_ImageB.Dispose();
      HOperatorSet.Decompose3(ho_ImageReduced, out ho_ImageR, out ho_ImageG, out ho_ImageB
          );
      ho_Region.Dispose();
      HOperatorSet.Threshold(ho_ImageB, out ho_Region, 60, 95);
      //
      //Extract color space of red pills
      ho_ImageReduced.Dispose();
      HOperatorSet.ReduceDomain(ho_Image, ho_PillType2, out ho_ImageReduced);
      ho_ImageR.Dispose();ho_ImageG.Dispose();ho_ImageB.Dispose();
      HOperatorSet.Decompose3(ho_ImageReduced, out ho_ImageR, out ho_ImageG, out ho_ImageB
          );
      ho_ImageInvert.Dispose();
      HOperatorSet.InvertImage(ho_ImageB, out ho_ImageInvert);
      ho_RegionHysteresis2.Dispose();
      HOperatorSet.HysteresisThreshold(ho_ImageInvert, out ho_RegionHysteresis2, 
          190, 200, 5);
      //
      //Extract color space of green pills
      ho_ImageReduced.Dispose();
      HOperatorSet.ReduceDomain(ho_Image, ho_PillType3, out ho_ImageReduced);
      ho_ImageR.Dispose();ho_ImageG.Dispose();ho_ImageB.Dispose();
      HOperatorSet.Decompose3(ho_ImageReduced, out ho_ImageR, out ho_ImageG, out ho_ImageB
          );
      ho_ImageInvert.Dispose();
      HOperatorSet.InvertImage(ho_ImageB, out ho_ImageInvert);
      ho_RegionHysteresis3.Dispose();
      HOperatorSet.HysteresisThreshold(ho_ImageInvert, out ho_RegionHysteresis3, 
          180, 200, 10);
      //
      {
      HObject ExpTmpOutVar_0;
      HOperatorSet.Intersection(ho_Region, ho_PillType1, out ExpTmpOutVar_0);
      ho_PillType1.Dispose();
      ho_PillType1 = ExpTmpOutVar_0;
      }
      {
      HObject ExpTmpOutVar_0;
      HOperatorSet.Intersection(ho_RegionHysteresis2, ho_PillType2, out ExpTmpOutVar_0
          );
      ho_PillType2.Dispose();
      ho_PillType2 = ExpTmpOutVar_0;
      }
      hv_PillTypeCount.Dispose();
      hv_PillTypeCount = new HTuple();
      hv_PillTypeCount[0] = 3;
      hv_PillTypeCount[1] = 6;
      hv_PillTypeCount[2] = 6;
      {
      HObject ExpTmpOutVar_0;
      HOperatorSet.Intersection(ho_RegionHysteresis3, ho_PillType3, out ExpTmpOutVar_0
          );
      ho_PillType3.Dispose();
      ho_PillType3 = ExpTmpOutVar_0;
      }
      ho_Classes.Dispose();
      HOperatorSet.ConcatObj(ho_PillType1, ho_PillType2, out ho_Classes);
      {
      HObject ExpTmpOutVar_0;
      HOperatorSet.ConcatObj(ho_Classes, ho_PillType3, out ExpTmpOutVar_0);
      ho_Classes.Dispose();
      ho_Classes = ExpTmpOutVar_0;
      }
      ho_Region.Dispose();
      ho_ConnectedRegions.Dispose();
      ho_SelectedRegions.Dispose();
      ho_Blister.Dispose();
      ho_Rectangle.Dispose();
      ho_Pattern.Dispose();
      ho_PillType1.Dispose();
      ho_PillType2.Dispose();
      ho_PillType3.Dispose();
      ho_ImageReduced.Dispose();
      ho_ImageR.Dispose();
      ho_ImageG.Dispose();
      ho_ImageB.Dispose();
      ho_ImageInvert.Dispose();
      ho_RegionHysteresis2.Dispose();
      ho_RegionHysteresis3.Dispose();

      hv_I.Dispose();
      hv_Row.Dispose();
      hv_J.Dispose();
      hv_Column.Dispose();
      hv_Area.Dispose();

      return;
    }
    catch (HalconException HDevExpDefaultException)
    {
      ho_Region.Dispose();
      ho_ConnectedRegions.Dispose();
      ho_SelectedRegions.Dispose();
      ho_Blister.Dispose();
      ho_Rectangle.Dispose();
      ho_Pattern.Dispose();
      ho_PillType1.Dispose();
      ho_PillType2.Dispose();
      ho_PillType3.Dispose();
      ho_ImageReduced.Dispose();
      ho_ImageR.Dispose();
      ho_ImageG.Dispose();
      ho_ImageB.Dispose();
      ho_ImageInvert.Dispose();
      ho_RegionHysteresis2.Dispose();
      ho_RegionHysteresis3.Dispose();

      hv_I.Dispose();
      hv_Row.Dispose();
      hv_J.Dispose();
      hv_Column.Dispose();
      hv_Area.Dispose();

      throw HDevExpDefaultException;
    }
  }

