    HTuple hv_PillTypeCount = new HTuple(), hv_NumClasses = new HTuple();
    HTuple hv_GMMHandle = new HTuple(), hv_Centers = new HTuple();
    HTuple hv_Iter = new HTuple(), hv_Count = new HTuple();
    HTuple hv_FileIndex = new HTuple(), hv_Phi = new HTuple();
    HTuple hv_Area1 = new HTuple(), hv_Row = new HTuple();
    HTuple hv_Column = new HTuple(), hv_HomMat2D = new HTuple();
    HTuple hv_Number = new HTuple(), hv_Index = new HTuple();
    HTuple hv_Area = new HTuple(), hv_Row1 = new HTuple();
    HTuple hv_Column1 = new HTuple(), hv_Mean = new HTuple();
    HTuple hv_Deviation = new HTuple(), hv_CountFinalClass = new HTuple();
    HTuple hv_Size = new HTuple();
    // Initialize local and output iconic variables 
    HOperatorSet.GenEmptyObj(out ho_Image);
    HOperatorSet.GenEmptyObj(out ho_Chambers);
    HOperatorSet.GenEmptyObj(out ho_ChambersUnion);
    HOperatorSet.GenEmptyObj(out ho_Classes);
    HOperatorSet.GenEmptyObj(out ho_Region);
    HOperatorSet.GenEmptyObj(out ho_ConnectedRegions);
    HOperatorSet.GenEmptyObj(out ho_SelectedRegions);
    HOperatorSet.GenEmptyObj(out ho_RegionTrans);
    HOperatorSet.GenEmptyObj(out ho_ImageAffineTrans);
    HOperatorSet.GenEmptyObj(out ho_ImageReduced);
    HOperatorSet.GenEmptyObj(out ho_ImageR);
    HOperatorSet.GenEmptyObj(out ho_ImageG);
    HOperatorSet.GenEmptyObj(out ho_ImageB);
    HOperatorSet.GenEmptyObj(out ho_ClassRegions);
    HOperatorSet.GenEmptyObj(out ho_FinalClasses);
    HOperatorSet.GenEmptyObj(out ho_ChambersRemaining);
    HOperatorSet.GenEmptyObj(out ho_PillsOfOneType);
    HOperatorSet.GenEmptyObj(out ho_RegionDifference);
    HOperatorSet.GenEmptyObj(out ho_MissingPills);
    HOperatorSet.GenEmptyObj(out ho_WrongPills);
    HOperatorSet.GenEmptyObj(out ho_WrongNumberOfPills);
    HOperatorSet.GenEmptyObj(out ho_LeftOvers);
    HOperatorSet.GenEmptyObj(out ho_ObjectSelected);
    try
    {
      //This example demonstrates an application from the pharmaceutical
      //industry. The task is to check the content of manually filled
      //blisters. The first image (reference) shows the combination, that
      //is requested. The subsequent images are then checked for this
      //setup drawn from the reference image. To perform this task we use
      //the gmm classifier, which will be trained with the reference image
      //in the beginning and is then used to classify the different pill
      //types in subsequent blister images.
      //
      if (HDevWindowStack.IsOpen())
      {
        HOperatorSet.CloseWindow(HDevWindowStack.Pop());
      }
      ho_Image.Dispose();
      HOperatorSet.ReadImage(out ho_Image, "blister/blister_mixed_reference");
      hv_WindowHandle.Dispose();
      dev_open_window_fit_image(ho_Image, 0, 0, -1, -1, out hv_WindowHandle);
      set_display_font(hv_WindowHandle, 14, "mono", "true", "false");
      dev_update_off();
      if (HDevWindowStack.IsOpen())
      {
        HOperatorSet.DispObj(ho_Image, HDevWindowStack.GetActive());
      }
      if (HDevWindowStack.IsOpen())
      {
        HOperatorSet.SetDraw(HDevWindowStack.GetActive(), "margin");
      }
      //
      //First, we extract the content of the blister and pass
      //this information on to the gmm classifier
      disp_message(hv_WindowHandle, "Train gmm classifier on pill types", "window", 
          12, 12, "black", "true");
      ho_Chambers.Dispose();ho_ChambersUnion.Dispose();ho_Classes.Dispose();hv_PhiRef.Dispose();hv_RowRef.Dispose();hv_ColumnRef.Dispose();hv_PillTypeCount.Dispose();
      extract_pill_types(ho_Image, out ho_Chambers, out ho_ChambersUnion, out ho_Classes, 
          out hv_PhiRef, out hv_RowRef, out hv_ColumnRef, out hv_PillTypeCount);
      hv_NumClasses.Dispose();
      using (HDevDisposeHelper dh = new HDevDisposeHelper())
      {
      hv_NumClasses = new HTuple(hv_PillTypeCount.TupleLength()
          );
      }
      hv_GMMHandle.Dispose();
      HOperatorSet.CreateClassGmm(3, 3, (new HTuple(1)).TupleConcat(5), "spherical", 
          "normalization", 10, 42, out hv_GMMHandle);
      HOperatorSet.AddSamplesImageClassGmm(ho_Image, ho_Classes, hv_GMMHandle, 0);
      hv_Centers.Dispose();hv_Iter.Dispose();
      HOperatorSet.TrainClassGmm(hv_GMMHandle, 100, 0.001, "training", 0.0001, out hv_Centers, 
          out hv_Iter);
      //
      //
      //Then, the subsequent blisters are tested for their right combination
      hv_Count.Dispose();
      hv_Count = 12;
      HTuple end_val29 = hv_Count;
      HTuple step_val29 = 1;
      for (hv_FileIndex=1; hv_FileIndex.Continue(end_val29, step_val29); hv_FileIndex = hv_FileIndex.TupleAdd(step_val29))
      {
        //
        //Align image read
        using (HDevDisposeHelper dh = new HDevDisposeHelper())
        {
        ho_Image.Dispose();
        HOperatorSet.ReadImage(out ho_Image, "blister/blister_mixed_"+(hv_FileIndex.TupleString(
            "02")));
        }
        ho_Region.Dispose();
        HOperatorSet.Threshold(ho_Image, out ho_Region, 90, 255);
        ho_ConnectedRegions.Dispose();
        HOperatorSet.Connection(ho_Region, out ho_ConnectedRegions);
        ho_SelectedRegions.Dispose();
        HOperatorSet.SelectShape(ho_ConnectedRegions, out ho_SelectedRegions, "area", 
            "and", 5000, 9999999);
        ho_RegionTrans.Dispose();
        HOperatorSet.ShapeTrans(ho_SelectedRegions, out ho_RegionTrans, "convex");
        hv_Phi.Dispose();
        HOperatorSet.OrientationRegion(ho_RegionTrans, out hv_Phi);
        if ((int)(new HTuple(((hv_Phi.TupleAbs())).TupleGreater((new HTuple(90)).TupleRad()
            ))) != 0)
        {
          using (HDevDisposeHelper dh = new HDevDisposeHelper())
          {
          {
          HTuple 
            ExpTmpLocalVar_Phi = ((new HTuple(180)).TupleRad()
              )+hv_Phi;
          hv_Phi.Dispose();
          hv_Phi = ExpTmpLocalVar_Phi;
          }
          }
        }
        hv_Area1.Dispose();hv_Row.Dispose();hv_Column.Dispose();
        HOperatorSet.AreaCenter(ho_RegionTrans, out hv_Area1, out hv_Row, out hv_Column);
        hv_HomMat2D.Dispose();
        HOperatorSet.VectorAngleToRigid(hv_Row, hv_Column, hv_Phi, hv_RowRef, hv_ColumnRef, 
            hv_PhiRef, out hv_HomMat2D);
        ho_ImageAffineTrans.Dispose();
        HOperatorSet.AffineTransImage(ho_Image, out ho_ImageAffineTrans, hv_HomMat2D, 
            "constant", "false");
        ho_ImageReduced.Dispose();
        HOperatorSet.ReduceDomain(ho_ImageAffineTrans, ho_ChambersUnion, out ho_ImageReduced
            );
        ho_ImageR.Dispose();ho_ImageG.Dispose();ho_ImageB.Dispose();
        HOperatorSet.Decompose3(ho_ImageAffineTrans, out ho_ImageR, out ho_ImageG, 
            out ho_ImageB);
        //
        //Classify pill type for each chamber
        ho_ClassRegions.Dispose();
        HOperatorSet.ClassifyImageClassGmm(ho_ImageReduced, out ho_ClassRegions, 
            hv_GMMHandle, 0.0005);
        //
        hv_Number.Dispose();
        HOperatorSet.CountObj(ho_ClassRegions, out hv_Number);
        ho_FinalClasses.Dispose();
        HOperatorSet.GenEmptyObj(out ho_FinalClasses);
        ho_ChambersRemaining.Dispose();
        HOperatorSet.Connection(ho_Chambers, out ho_ChambersRemaining);
        HTuple end_val53 = 1;
        HTuple step_val53 = -1;
        for (hv_Index=hv_Number; hv_Index.Continue(end_val53, step_val53); hv_Index = hv_Index.TupleAdd(step_val53))
        {
          if (HDevWindowStack.IsOpen())
          {
            HOperatorSet.ClearWindow(HDevWindowStack.GetActive());
          }
          ho_Region.Dispose();
          HOperatorSet.SelectObj(ho_ClassRegions, out ho_Region, hv_Index);
          {
          HObject ExpTmpOutVar_0;
          HOperatorSet.Intersection(ho_ChambersRemaining, ho_Region, out ExpTmpOutVar_0
              );
          ho_Region.Dispose();
          ho_Region = ExpTmpOutVar_0;
          }
          ho_PillsOfOneType.Dispose();
          HOperatorSet.SelectShape(ho_Region, out ho_PillsOfOneType, (new HTuple("area")).TupleConcat(
              "width"), "and", (new HTuple(200)).TupleConcat(40), (new HTuple(3000)).TupleConcat(
              80));
          ho_RegionDifference.Dispose();
          HOperatorSet.Difference(ho_ChambersUnion, ho_PillsOfOneType, out ho_RegionDifference
              );
          ho_ConnectedRegions.Dispose();
          HOperatorSet.Connection(ho_RegionDifference, out ho_ConnectedRegions);
          ho_SelectedRegions.Dispose();
          HOperatorSet.SelectShape(ho_ConnectedRegions, out ho_SelectedRegions, "area", 
              "and", 0, 7868);
          {
          HObject ExpTmpOutVar_0;
          HOperatorSet.ShapeTrans(ho_SelectedRegions, out ExpTmpOutVar_0, "convex");
          ho_SelectedRegions.Dispose();
          ho_SelectedRegions = ExpTmpOutVar_0;
          }
          {
          HObject ExpTmpOutVar_0;
          HOperatorSet.Union1(ho_SelectedRegions, out ExpTmpOutVar_0);
          ho_SelectedRegions.Dispose();
          ho_SelectedRegions = ExpTmpOutVar_0;
          }
          {
          HObject ExpTmpOutVar_0;
          HOperatorSet.Difference(ho_ChambersRemaining, ho_SelectedRegions, out ExpTmpOutVar_0
              );
          ho_ChambersRemaining.Dispose();
          ho_ChambersRemaining = ExpTmpOutVar_0;
          }
          {
          HObject ExpTmpOutVar_0;
          HOperatorSet.ConcatObj(ho_SelectedRegions, ho_FinalClasses, out ExpTmpOutVar_0
              );
          ho_FinalClasses.Dispose();
          ho_FinalClasses = ExpTmpOutVar_0;
          }
        }
        //
        //
        //Check for right combination
        ho_MissingPills.Dispose();
        HOperatorSet.GenEmptyObj(out ho_MissingPills);
        ho_WrongPills.Dispose();
        HOperatorSet.GenEmptyObj(out ho_WrongPills);
        ho_WrongNumberOfPills.Dispose();
        HOperatorSet.GenEmptyObj(out ho_WrongNumberOfPills);
        ho_LeftOvers.Dispose();
        HOperatorSet.Difference(ho_ChambersUnion, ho_FinalClasses, out ho_LeftOvers
            );
        hv_Area.Dispose();hv_Row1.Dispose();hv_Column1.Dispose();
        HOperatorSet.AreaCenter(ho_LeftOvers, out hv_Area, out hv_Row1, out hv_Column1);
        if ((int)(new HTuple(hv_Area.TupleGreater(0))) != 0)
        {
          {
          HObject ExpTmpOutVar_0;
          HOperatorSet.Connection(ho_LeftOvers, out ExpTmpOutVar_0);
          ho_LeftOvers.Dispose();
          ho_LeftOvers = ExpTmpOutVar_0;
          }
          hv_Number.Dispose();
          HOperatorSet.CountObj(ho_LeftOvers, out hv_Number);
          HTuple end_val77 = hv_Number;
          HTuple step_val77 = 1;
          for (hv_Index=1; hv_Index.Continue(end_val77, step_val77); hv_Index = hv_Index.TupleAdd(step_val77))
          {
            ho_ObjectSelected.Dispose();
            HOperatorSet.SelectObj(ho_LeftOvers, out ho_ObjectSelected, hv_Index);
            hv_Mean.Dispose();hv_Deviation.Dispose();
            HOperatorSet.Intensity(ho_ObjectSelected, ho_ImageB, out hv_Mean, out hv_Deviation);
            if ((int)(new HTuple(hv_Deviation.TupleGreater(40))) != 0)
            {
              {
              HObject ExpTmpOutVar_0;
              HOperatorSet.ConcatObj(ho_WrongPills, ho_ObjectSelected, out ExpTmpOutVar_0
                  );
              ho_WrongPills.Dispose();
              ho_WrongPills = ExpTmpOutVar_0;
              }
            }
            else
            {
              {
              HObject ExpTmpOutVar_0;
              HOperatorSet.ConcatObj(ho_MissingPills, ho_ObjectSelected, out ExpTmpOutVar_0
                  );
              ho_MissingPills.Dispose();
              ho_MissingPills = ExpTmpOutVar_0;
              }
            }
          }
        }
        //
        //Compute histogram
        hv_CountFinalClass.Dispose();
        hv_CountFinalClass = new HTuple();
        HTuple end_val90 = hv_NumClasses;
        HTuple step_val90 = 1;
        for (hv_Index=1; hv_Index.Continue(end_val90, step_val90); hv_Index = hv_Index.TupleAdd(step_val90))
        {
          ho_ObjectSelected.Dispose();
          HOperatorSet.SelectObj(ho_FinalClasses, out ho_ObjectSelected, hv_Index);
          {
          HObject ExpTmpOutVar_0;
          HOperatorSet.Connection(ho_ObjectSelected, out ExpTmpOutVar_0);
          ho_ObjectSelected.Dispose();
          ho_ObjectSelected = ExpTmpOutVar_0;
          }
          hv_Size.Dispose();
          HOperatorSet.CountObj(ho_ObjectSelected, out hv_Size);
          using (HDevDisposeHelper dh = new HDevDisposeHelper())
          {
          {
          HTuple 
            ExpTmpLocalVar_CountFinalClass = hv_CountFinalClass.TupleConcat(
              hv_Size);
          hv_CountFinalClass.Dispose();
          hv_CountFinalClass = ExpTmpLocalVar_CountFinalClass;
          }
          }
        }
        //
        //Display classification results and output allover statistic
        display_results(ho_ImageAffineTrans, ho_LeftOvers, ho_FinalClasses, ho_WrongPills, 
            hv_CountFinalClass, hv_PillTypeCount, hv_WindowHandle);
        if ((int)(new HTuple(hv_FileIndex.TupleLess(hv_Count))) != 0)
        {
          disp_continue_message(hv_WindowHandle, "black", "true");
        }
        // stop(...); only in hdevelop
      }

    }
    catch (HalconException HDevExpDefaultException)
    {
      ho_Image.Dispose();
      ho_Chambers.Dispose();
      ho_ChambersUnion.Dispose();
      ho_Classes.Dispose();
      ho_Region.Dispose();
      ho_ConnectedRegions.Dispose();
      ho_SelectedRegions.Dispose();
      ho_RegionTrans.Dispose();
      ho_ImageAffineTrans.Dispose();
      ho_ImageReduced.Dispose();
      ho_ImageR.Dispose();
      ho_ImageG.Dispose();
      ho_ImageB.Dispose();
      ho_ClassRegions.Dispose();
      ho_FinalClasses.Dispose();
      ho_ChambersRemaining.Dispose();
      ho_PillsOfOneType.Dispose();
      ho_RegionDifference.Dispose();
      ho_MissingPills.Dispose();
      ho_WrongPills.Dispose();
      ho_WrongNumberOfPills.Dispose();
      ho_LeftOvers.Dispose();
      ho_ObjectSelected.Dispose();

      hv_WindowHandle.Dispose();
      hv_PhiRef.Dispose();
      hv_RowRef.Dispose();
      hv_ColumnRef.Dispose();
      hv_PillTypeCount.Dispose();
      hv_NumClasses.Dispose();
      hv_GMMHandle.Dispose();
      hv_Centers.Dispose();
      hv_Iter.Dispose();
      hv_Count.Dispose();
      hv_FileIndex.Dispose();
      hv_Phi.Dispose();
      hv_Area1.Dispose();
      hv_Row.Dispose();
      hv_Column.Dispose();
      hv_HomMat2D.Dispose();
      hv_Number.Dispose();
      hv_Index.Dispose();
      hv_Area.Dispose();
      hv_Row1.Dispose();
      hv_Column1.Dispose();
      hv_Mean.Dispose();
      hv_Deviation.Dispose();
      hv_CountFinalClass.Dispose();
      hv_Size.Dispose();

      throw HDevExpDefaultException;
    }
    ho_Image.Dispose();
    ho_Chambers.Dispose();
    ho_ChambersUnion.Dispose();
    ho_Classes.Dispose();
    ho_Region.Dispose();
    ho_ConnectedRegions.Dispose();
    ho_SelectedRegions.Dispose();
    ho_RegionTrans.Dispose();
    ho_ImageAffineTrans.Dispose();
    ho_ImageReduced.Dispose();
    ho_ImageR.Dispose();
    ho_ImageG.Dispose();
    ho_ImageB.Dispose();
    ho_ClassRegions.Dispose();
    ho_FinalClasses.Dispose();
    ho_ChambersRemaining.Dispose();
    ho_PillsOfOneType.Dispose();
    ho_RegionDifference.Dispose();
    ho_MissingPills.Dispose();
    ho_WrongPills.Dispose();
    ho_WrongNumberOfPills.Dispose();
    ho_LeftOvers.Dispose();
    ho_ObjectSelected.Dispose();

    hv_WindowHandle.Dispose();
    hv_PhiRef.Dispose();
    hv_RowRef.Dispose();
    hv_ColumnRef.Dispose();
    hv_PillTypeCount.Dispose();
    hv_NumClasses.Dispose();
    hv_GMMHandle.Dispose();
    hv_Centers.Dispose();
    hv_Iter.Dispose();
    hv_Count.Dispose();
    hv_FileIndex.Dispose();
    hv_Phi.Dispose();
    hv_Area1.Dispose();
    hv_Row.Dispose();
    hv_Column.Dispose();
    hv_HomMat2D.Dispose();
    hv_Number.Dispose();
    hv_Index.Dispose();
    hv_Area.Dispose();
    hv_Row1.Dispose();
    hv_Column1.Dispose();
    hv_Mean.Dispose();
    hv_Deviation.Dispose();
    hv_CountFinalClass.Dispose();
    hv_Size.Dispose();

  }

#endif


